mapper.insert:
SELECT 'ANN' || LPAD( NVL(MAX(TO_NUMBER(REGEXP_REPLACE(ann_no, '[^0-9]', ''))), 0) + 1 , 4, '0') FROM center_ann_board_post
/* kr.or.ddit.domain.central.admin.mapper.AnnouncementMapper.insertAnnouncement */ /* 공고 등록 */
INSERT INTO center_ann_board_post ( ann_no /** 공고번호 */ , board_no /** 게시판번호 */ , ttl /** 제목 */ , cn /** 내용 */ , wrtr_id /** 작성자아이디 */ , top_fix_yn /** 상단고정여부 */ , pblanc_bgng_dt /** 공고게시시작일 */ , pblanc_end_dt /** 공고게시종료일 */ , rcrt_bgng_dt /** 모집시작일 */ , rcrt_end_dt /** 모집종료일 */ , reg_dttm /** 등록일시 */ , inq_cnt /** 조회수 */ , sbmsn_doc /** 제출서류 */ , atch_file_id /** 첨부파일ID */ , del_yn /** 삭제여부 */ , opn_yn /** 공개여부 */ ) VALUES ( #{annNo} , ( SELECT board_no FROM ( SELECT cbi.board_no FROM center_board_instance cbi WHERE cbi.apt_cmplex_no = #{aptCmplexNo} AND NVL(cbi.use_yn, 'Y') = 'Y' AND ( cbi.board_ty_cd = 'ANN' OR cbi.board_nm LIKE '%공고%' ) ORDER BY cbi.board_no ) WHERE ROWNUM = 1 ) , #{ttl} , #{cn} , #{wrtrId} , NVL(#{topFixYn}, 'N') , TO_DATE(#{pblancBgngDt}, 'YYYY-MM-DD') , TO_DATE(#{pblancEndDt}, 'YYYY-MM-DD') , TO_DATE(#{rcrtBgngDt}, 'YYYY-MM-DD') , TO_DATE(#{rcrtEndDt}, 'YYYY-MM-DD') , SYSDATE , 0 , #{sbmsnDoc} , #{atchFileId} , NVL(#{delYn}, 'N') , NVL(#{opnYn}, 'Y') )

mapper.update:
        /* kr.or.ddit.domain.central.admin.mapper.AnnouncementMapper.deleteAnnouncement */
        /* 공고 삭제 처리 */

        UPDATE center_ann_board_post
        SET
        del_yn = 'Y'       /** 삭제여부 */
        , mdf_dttm = SYSDATE /** 수정일시 */
        WHERE ann_no = #{annNo}

mapper.select:
/* 단지 상세정보 조회 */
SELECT ac.apt_cmplex_no AS aptCmplexNo , ac.apt_cmplex_nm AS aptCmplexNm , ac.dorojuso AS dorojuso
/* 전체 세대수 조회
apt_unit의 세대수를 모두 합산. */ , NVL(( SELECT SUM(NVL(au.unit_cnt, 0)) FROM apt_unit au WHERE au.apt_cmplex_no = ac.apt_cmplex_no ), 0) AS unitCnt
FROM apt_complex ac
WHERE ac.apt_cmplex_no = #{aptCmplexNo}
